#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="E:\MiacodeDocs\node_modules\.pnpm\vitepress@1.6.4_@algolia+cl_587a628595cb98ee078a76b320bc2fe3\node_modules\vitepress\node_modules;E:\MiacodeDocs\node_modules\.pnpm\vitepress@1.6.4_@algolia+cl_587a628595cb98ee078a76b320bc2fe3\node_modules;E:\MiacodeDocs\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/e/MiacodeDocs/node_modules/.pnpm/vitepress@1.6.4_@algolia+cl_587a628595cb98ee078a76b320bc2fe3/node_modules/vitepress/node_modules:/mnt/e/MiacodeDocs/node_modules/.pnpm/vitepress@1.6.4_@algolia+cl_587a628595cb98ee078a76b320bc2fe3/node_modules:/mnt/e/MiacodeDocs/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../vitepress/bin/vitepress.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../vitepress/bin/vitepress.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../vitepress/bin/vitepress.js" $args
  } else {
    & "node$exe"  "$basedir/../vitepress/bin/vitepress.js" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
